#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--)
	{
	    int n,k;
	    cin>>n>>k;
	    string s;
	    cin>>s;
	    unordered_map<char,int>mp;
	    mp['G']=1;
	    mp['I']=2;
	    int x=0;
	    for(int i=0;i<n;i++)
	    {
	        if(s[i]=='I') x++;
	        else break;
	    }
	    int w1=-1,w2=-1;
	
	    while(x<n)
	    {
	        if(s[x]=='G' && w1==-1 && w2==-1)
	        {
	            w1=k;
	            x++;
	        }
	        else if(s[x]=='I' && w2==-1)
	        {
	            x++;
	        }
	        else
	        {
                //cout<<x<<endl;
	            while(x<n && w1-mp[s[x]]>=0)
	            {
	                w1-=mp[s[x]];
	                x++;
	            }
	            //cout<<x<<endl;
	            w2=k;
	            x++;
	            while(x<n && (w2-mp[s[x]]>=0 || w1-mp[s[x]]>=0))
	            {
	                if(w1-mp[s[x]]>=0)
	                {
	                    w1-=mp[s[x]];
	                    x++;
	                }
	                else
	                {
	                    w2-=mp[s[x]];
	                    x++;
	                }
	            }
	            if(x<n && !(w2-mp[s[x]]>=0 || w1-mp[s[x]]>=0))
	            {
	                break;
	            }
	            //cout<<x<<endl;
	            //if(w2==0) break;
	        }
	    }
	    if(x!=n) cout<<"NO"<<endl;
	    else cout<<"YES"<<endl;
	    
	}
	return 0;

}
